window.CHUJI_DATA_11 = [{"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 1, "type": "reading", "en": "Did the Italian explorer Christopher Columbus really discover America?", "zh": "真的是意大利探险家克里斯多弗·哥伦布发现美洲的吗？", "audio": "chuji_l101_01.mp3", "localAudio": "audio_chunks/chuji_l101_01.mp3", "b64": "", "src": "chuji"}, {"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 2, "type": "reading", "en": "It's believed that travelers from China got there first.", "zh": "一般相信来自中国的旅行者最先到达那里。", "audio": "chuji_l101_02.mp3", "localAudio": "audio_chunks/chuji_l101_02.mp3", "b64": "", "src": "chuji"}, {"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 3, "type": "reading", "en": "They crossed the Pacific to Mexico in the fifth century.", "zh": "他们在第5世纪时即横渡太平洋到了墨西哥。", "audio": "chuji_l101_03.mp3", "localAudio": "audio_chunks/chuji_l101_03.mp3", "b64": "", "src": "chuji"}, {"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 4, "type": "reading", "en": "In fact, Columbus landed in the Bahamas in 1492 and never got to North America.", "zh": "事实上，哥伦布在1492年登陆巴哈马群岛，但却未曾到达北美洲。", "audio": "chuji_l101_04.mp3", "localAudio": "audio_chunks/chuji_l101_04.mp3", "b64": "", "src": "chuji"}, {"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 5, "type": "reading", "en": "America was not even named after Christopher Columbus.", "zh": "美洲甚至不是以克里斯多弗·哥伦布的名字命名的。", "audio": "chuji_l101_05.mp3", "localAudio": "audio_chunks/chuji_l101_05.mp3", "b64": "", "src": "chuji"}, {"l": 401, "lt": "Lesson 101 Who Discovered America? 谁发现了美洲？", "i": 6, "type": "reading", "en": "It was named after Amerigo Vespucci, who landed in America in the late fifteenth century.", "zh": "它是以亚美利哥·维斯浦奇的名字命名的，他在15世纪末登陆美洲。", "audio": "chuji_l101_06.mp3", "localAudio": "audio_chunks/chuji_l101_06.mp3", "b64": "", "src": "chuji"}, {"l": 402, "lt": "Lesson 102 The Same First Name 同名", "i": 1, "type": "dialog", "en": "How come you have the same first name as your father?", "zh": "为什么你跟你父亲同名呢？", "audio": "chuji_l102_01.mp3", "localAudio": "audio_chunks/chuji_l102_01.mp3", "b64": "", "src": "chuji", "speaker": "Molly", "note": "说话人: Molly"}, {"l": 402, "lt": "Lesson 102 The Same First Name 同名", "i": 2, "type": "dialog", "en": "I was named after him.", "zh": "我是随他的名字取的。", "audio": "chuji_l102_02.mp3", "localAudio": "audio_chunks/chuji_l102_02.mp3", "b64": "", "src": "chuji", "speaker": "Junior", "note": "说话人: Junior"}, {"l": 402, "lt": "Lesson 102 The Same First Name 同名", "i": 3, "type": "dialog", "en": "What about your sister?", "zh": "那你的妹妹呢？", "audio": "chuji_l102_03.mp3", "localAudio": "audio_chunks/chuji_l102_03.mp3", "b64": "", "src": "chuji", "speaker": "Molly", "note": "说话人: Molly"}, {"l": 402, "lt": "Lesson 102 The Same First Name 同名", "i": 4, "type": "dialog", "en": "She was named after my grandmother.", "zh": "她是随我祖母的名字取的。", "audio": "chuji_l102_04.mp3", "localAudio": "audio_chunks/chuji_l102_04.mp3", "b64": "", "src": "chuji", "speaker": "Junior", "note": "说话人: Junior"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 1, "type": "reading", "en": "Why do people get headaches in a crowded, stuffy room?", "zh": "为什么人们在又挤又闷的房间中会头疼呢？", "audio": "chuji_l103_01.mp3", "localAudio": "audio_chunks/chuji_l103_01.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 2, "type": "reading", "en": "Because they are breathing bad air.", "zh": "因为他们呼吸着恶劣的空气。", "audio": "chuji_l103_02.mp3", "localAudio": "audio_chunks/chuji_l103_02.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 3, "type": "reading", "en": "People who breathe bad air for a long time can get really sick.", "zh": "凡是长时间呼吸恶劣空气的人可能会生重病。", "audio": "chuji_l103_03.mp3", "localAudio": "audio_chunks/chuji_l103_03.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 4, "type": "reading", "en": "They may even get lung cancer and die.", "zh": "他们甚至可能得肺癌死去。", "audio": "chuji_l103_04.mp3", "localAudio": "audio_chunks/chuji_l103_04.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 5, "type": "reading", "en": "People need fresh air.", "zh": "人们需要新鲜空气。", "audio": "chuji_l103_05.mp3", "localAudio": "audio_chunks/chuji_l103_05.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 6, "type": "reading", "en": "Fresh air cleans the blood.", "zh": "新鲜空气能净化血液。", "audio": "chuji_l103_06.mp3", "localAudio": "audio_chunks/chuji_l103_06.mp3", "b64": "", "src": "chuji"}, {"l": 403, "lt": "Lesson 103 Air Pollution 空气污染", "i": 7, "type": "reading", "en": "For our health's sake, we should all, therefore, do our part to fight against air pollution.", "zh": "为了健康起见，我们每个人都应该尽一己之力为反对空气污染而努力。", "audio": "chuji_l103_07.mp3", "localAudio": "audio_chunks/chuji_l103_07.mp3", "b64": "", "src": "chuji"}, {"l": 404, "lt": "Lesson 104 We Need Fresh Air 我们需要新鲜空气", "i": 1, "type": "dialog", "en": "Boy, it's really stuffy in here.", "zh": "乖乖，这里面可真闷啊。", "audio": "chuji_l104_01.mp3", "localAudio": "audio_chunks/chuji_l104_01.mp3", "b64": "", "src": "chuji", "speaker": "Joan", "note": "说话人: Joan"}, {"l": 404, "lt": "Lesson 104 We Need Fresh Air 我们需要新鲜空气", "i": 2, "type": "dialog", "en": "You're right. We need some fresh air.", "zh": "你说得对。我们需要些新鲜空气。", "audio": "chuji_l104_02.mp3", "localAudio": "audio_chunks/chuji_l104_02.mp3", "b64": "", "src": "chuji", "speaker": "Drake", "note": "说话人: Drake"}, {"l": 404, "lt": "Lesson 104 We Need Fresh Air 我们需要新鲜空气", "i": 3, "type": "dialog", "en": "Let's turn on the air-con.", "zh": "咱们打开空调吧。", "audio": "chuji_l104_03.mp3", "localAudio": "audio_chunks/chuji_l104_03.mp3", "b64": "", "src": "chuji", "speaker": "Joan", "note": "说话人: Joan"}, {"l": 404, "lt": "Lesson 104 We Need Fresh Air 我们需要新鲜空气", "i": 4, "type": "dialog", "en": "Why not just open the window?", "zh": "为何不干脆打开窗户呢？", "audio": "chuji_l104_04.mp3", "localAudio": "audio_chunks/chuji_l104_04.mp3", "b64": "", "src": "chuji", "speaker": "Drake", "note": "说话人: Drake"}, {"l": 404, "lt": "Lesson 104 We Need Fresh Air 我们需要新鲜空气", "i": 5, "type": "dialog", "en": "That's even better.", "zh": "那就更好了。", "audio": "chuji_l104_05.mp3", "localAudio": "audio_chunks/chuji_l104_05.mp3", "b64": "", "src": "chuji", "speaker": "Joan", "note": "说话人: Joan"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 1, "type": "reading", "en": "Garbage disposal is a major problem in most cities around the world.", "zh": "垃圾处理在世界各地的大部分城市里是个大问题。", "audio": "chuji_l105_01.mp3", "localAudio": "audio_chunks/chuji_l105_01.mp3", "b64": "", "src": "chuji"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 2, "type": "reading", "en": "Finding places for garbage is getting more and more difficult.", "zh": "寻找垃圾处理场越来越困难了。", "audio": "chuji_l105_02.mp3", "localAudio": "audio_chunks/chuji_l105_02.mp3", "b64": "", "src": "chuji"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 3, "type": "reading", "en": "Recycling is, therefore, becoming very popular.", "zh": "因此，资源回收变得很普遍。", "audio": "chuji_l105_03.mp3", "localAudio": "audio_chunks/chuji_l105_03.mp3", "b64": "", "src": "chuji"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 4, "type": "reading", "en": "In other words, more and more people are treating used material so that it can be reused.", "zh": "换言之，越来越多人在处理使用过的东西以便重新加以利用。", "audio": "chuji_l105_04.mp3", "localAudio": "audio_chunks/chuji_l105_04.mp3", "b64": "", "src": "chuji"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 5, "type": "reading", "en": "There is no doubt that recycling helps save our precious natural resources.", "zh": "毫无疑问，资源回收有助于节省珍贵的自然资源。", "audio": "chuji_l105_05.mp3", "localAudio": "audio_chunks/chuji_l105_05.mp3", "b64": "", "src": "chuji"}, {"l": 405, "lt": "Lesson 105 Recycling 资源回收再利用", "i": 6, "type": "reading", "en": "It is in our own best interest to recycle.", "zh": "资源回收对我们是最有利的。", "audio": "chuji_l105_06.mp3", "localAudio": "audio_chunks/chuji_l105_06.mp3", "b64": "", "src": "chuji"}, {"l": 406, "lt": "Lesson 106 Litterbugs 垃圾虫", "i": 1, "type": "dialog", "en": "Why is there so much garbage in the street, Mom?", "zh": "妈妈，为什么街上有这么多垃圾呢？", "audio": "chuji_l106_01.mp3", "localAudio": "audio_chunks/chuji_l106_01.mp3", "b64": "", "src": "chuji", "speaker": "Child", "note": "说话人: Child"}, {"l": 406, "lt": "Lesson 106 Litterbugs 垃圾虫", "i": 2, "type": "dialog", "en": "Because there are many litterbugs.", "zh": "因为有很多垃圾虫。", "audio": "chuji_l106_02.mp3", "localAudio": "audio_chunks/chuji_l106_02.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 406, "lt": "Lesson 106 Litterbugs 垃圾虫", "i": 3, "type": "dialog", "en": "What are litterbugs?", "zh": "什么是垃圾虫呢？", "audio": "chuji_l106_03.mp3", "localAudio": "audio_chunks/chuji_l106_03.mp3", "b64": "", "src": "chuji", "speaker": "Child", "note": "说话人: Child"}, {"l": 406, "lt": "Lesson 106 Litterbugs 垃圾虫", "i": 4, "type": "dialog", "en": "They're people who don't put their rubbish in trash cans.", "zh": "就是那些不把垃圾丢在垃圾箱里的人。", "audio": "chuji_l106_04.mp3", "localAudio": "audio_chunks/chuji_l106_04.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 1, "type": "reading", "en": "Hong Ying, who comes from Guangdong, is known as the oldest person in China.", "zh": "籍贯广东的洪英（译音）是中国众所周知最长寿的老人。", "audio": "chuji_l107_01.mp3", "localAudio": "audio_chunks/chuji_l107_01.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 2, "type": "reading", "en": "She is 122 years old.", "zh": "她现年122岁。", "audio": "chuji_l107_02.mp3", "localAudio": "audio_chunks/chuji_l107_02.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 3, "type": "reading", "en": "Although she can hardly hear, her voice is loud and clear.", "zh": "虽然她几乎听不见，但她的声音宏亮又清晰。", "audio": "chuji_l107_03.mp3", "localAudio": "audio_chunks/chuji_l107_03.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 4, "type": "reading", "en": "In fact, she is still full of life.", "zh": "事实上，她仍充满了生命力。", "audio": "chuji_l107_04.mp3", "localAudio": "audio_chunks/chuji_l107_04.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 5, "type": "reading", "en": "What's the secret of her longevity?", "zh": "她长寿的秘诀是什么呢？", "audio": "chuji_l107_05.mp3", "localAudio": "audio_chunks/chuji_l107_05.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 6, "type": "reading", "en": "Maybe it's her personality.", "zh": "也许在于她的个性。", "audio": "chuji_l107_06.mp3", "localAudio": "audio_chunks/chuji_l107_06.mp3", "b64": "", "src": "chuji"}, {"l": 407, "lt": "Lesson 107 The Secret of Longevity 长寿的秘诀", "i": 7, "type": "reading", "en": "According to her family and friends, she is humorous and easy to get along with.", "zh": "据她的家人和朋友说，她很幽默也容易相处。", "audio": "chuji_l107_07.mp3", "localAudio": "audio_chunks/chuji_l107_07.mp3", "b64": "", "src": "chuji"}, {"l": 408, "lt": "Lesson 108 Slow Down 慢下来", "i": 1, "type": "dialog", "en": "Slow down, Carl. I can't keep up with you.", "zh": "卡尔，走慢一点。我跟不上你。", "audio": "chuji_l108_01.mp3", "localAudio": "audio_chunks/chuji_l108_01.mp3", "b64": "", "src": "chuji", "speaker": "Rosa", "note": "说话人: Rosa"}, {"l": 408, "lt": "Lesson 108 Slow Down 慢下来", "i": 2, "type": "dialog", "en": "You walk as slowly as a snail.", "zh": "你走得跟蜗牛·…样慢。", "audio": "chuji_l108_02.mp3", "localAudio": "audio_chunks/chuji_l108_02.mp3", "b64": "", "src": "chuji", "speaker": "Carl", "note": "说话人: Carl"}, {"l": 408, "lt": "Lesson 108 Slow Down 慢下来", "i": 3, "type": "dialog", "en": "How do you keep so fit?", "zh": "你是怎么保持这么健康的呢？", "audio": "chuji_l108_03.mp3", "localAudio": "audio_chunks/chuji_l108_03.mp3", "b64": "", "src": "chuji", "speaker": "Rosa", "note": "说话人: Rosa"}, {"l": 408, "lt": "Lesson 108 Slow Down 慢下来", "i": 4, "type": "dialog", "en": "I work out as often as I can.", "zh": "我尽可能地经常运动。", "audio": "chuji_l108_04.mp3", "localAudio": "audio_chunks/chuji_l108_04.mp3", "b64": "", "src": "chuji", "speaker": "Carl", "note": "说话人: Carl"}, {"l": 409, "lt": "Lesson 109 Discovering Africa 探索非洲", "i": 1, "type": "reading", "en": "David Livingstone was a doctor and explorer from Scotland.", "zh": "大卫·李文斯顿是来自苏格兰的医生及探险家。", "audio": "chuji_l109_01.mp3", "localAudio": "audio_chunks/chuji_l109_01.mp3", "b64": "", "src": "chuji"}, {"l": 409, "lt": "Lesson 109 Discovering Africa 探索非洲", "i": 2, "type": "reading", "en": "He is famous for traveling 29,000 miles in Africa during the 19th century.", "zh": "他于19世纪在非洲旅行了29000英里而声名大噪。", "audio": "chuji_l109_02.mp3", "localAudio": "audio_chunks/chuji_l109_02.mp3", "b64": "", "src": "chuji"}, {"l": 409, "lt": "Lesson 109 Discovering Africa 探索非洲", "i": 3, "type": "reading", "en": "He discovered many rivers, lakes and mountains, including the Victoria Falls, the biggest waterfall in the world.", "zh": "他发现了许多河流、湖泊及山脉，包括世界最大的瀑布维多利亚瀑布。", "audio": "chuji_l109_03.mp3", "localAudio": "audio_chunks/chuji_l109_03.mp3", "b64": "", "src": "chuji"}, {"l": 409, "lt": "Lesson 109 Discovering Africa 探索非洲", "i": 4, "type": "reading", "en": "Most of all, he is highly respected because he helped to abolish slave trade in Africa.", "zh": "最重要的是，他因促成废除非洲的奴隶买卖而备受尊敬。", "audio": "chuji_l109_04.mp3", "localAudio": "audio_chunks/chuji_l109_04.mp3", "b64": "", "src": "chuji"}, {"l": 410, "lt": "Lesson 110 Easier Said Than Done 说来容易做来难", "i": 1, "type": "dialog", "en": "Don't be a slave to work, Ralph!", "zh": "拉尔夫，别成为工作的奴隶！", "audio": "chuji_l110_01.mp3", "localAudio": "audio_chunks/chuji_l110_01.mp3", "b64": "", "src": "chuji", "speaker": "Tina", "note": "说话人: Tina"}, {"l": 410, "lt": "Lesson 110 Easier Said Than Done 说来容易做来难", "i": 2, "type": "dialog", "en": "I can't help it. I'm always busy.", "zh": "我没办法。我总是很忙。", "audio": "chuji_l110_02.mp3", "localAudio": "audio_chunks/chuji_l110_02.mp3", "b64": "", "src": "chuji", "speaker": "Ralph", "note": "说话人: Ralph"}, {"l": 410, "lt": "Lesson 110 Easier Said Than Done 说来容易做来难", "i": 3, "type": "dialog", "en": "You have to take it easy sometimes.", "zh": "你有时必须放轻松点。", "audio": "chuji_l110_03.mp3", "localAudio": "audio_chunks/chuji_l110_03.mp3", "b64": "", "src": "chuji", "speaker": "Tina", "note": "说话人: Tina"}, {"l": 410, "lt": "Lesson 110 Easier Said Than Done 说来容易做来难", "i": 4, "type": "dialog", "en": "Easier said than done.", "zh": "说来容易做来难。", "audio": "chuji_l110_04.mp3", "localAudio": "audio_chunks/chuji_l110_04.mp3", "b64": "", "src": "chuji", "speaker": "Ralph", "note": "说话人: Ralph"}];